#include <iostream>
#include <iomanip>
#include <cmath>
#include <vector>
#include <algorithm>
#include <cstdint>
using namespace std;

struct Light {
    double x, y, alpha;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    double l, r;
    cin >> n >> l >> r;

    const double PI = acos(-1.0);
    vector<Light> p(n);

    for (auto& light : p) {
        cin >> light.x >> light.y >> light.alpha;
        light.alpha *= PI / 180.0;
    }

    auto calc = [&](int idx, double s) {
        double beta = p[idx].alpha - atan2(p[idx].x - s, p[idx].y);
        return p[idx].x + tan(beta) * p[idx].y;
    };

    if (n == 0) {
        cout << fixed << setprecision(9) << 0.0 << '\n';
        return 0;
    }

    int combinations[22][22] = {};
    combinations[0][0] = 1;
    for (int i = 1; i <= n; ++i) {
        combinations[i][0] = combinations[i][i] = 1;
        for (int j = 1; j < i; ++j)
            combinations[i][j] =
                combinations[i - 1][j - 1] + combinations[i - 1][j];
    }

    double answer = 0.0;
    vector<double> previous(n);

    for (int i = 0; i < n; ++i) {
        previous[i] = max(l, calc(i, l));
        answer = max(answer, previous[i] - l);
    }

    const uint32_t limit = uint32_t{1} << n;

    for (int size = 2; size <= n; ++size) {
        vector<double> current(
            static_cast<size_t>(combinations[n][size]) * size
        );

        uint32_t mask = (uint32_t{1} << size) - 1;
        size_t currentRank = 0;

        while (mask < limit) {
            int bits[21];
            int bitCount = 0;

            for (int bit = 0; bit < n; ++bit) {
                if (mask & (uint32_t{1} << bit))
                    bits[bitCount++] = bit;
            }

            int prefix[22] = {};
            int suffix[22] = {};

            for (int i = 0; i < size; ++i)
                prefix[i + 1] =
                    prefix[i] + combinations[bits[i]][i + 1];

            for (int i = size - 1; i >= 0; --i)
                suffix[i] =
                    suffix[i + 1] + combinations[bits[i]][i];

            for (int removed = 0; removed < size; ++removed) {
                int parentRank = prefix[removed] + suffix[removed + 1];
                size_t parentBase =
                    static_cast<size_t>(parentRank) * (size - 1);

                double value = l;

                for (int pos = 0; pos < size; ++pos) {
                    if (pos == removed)
                        continue;

                    int parentPosition = pos - (pos > removed);
                    value = max(
                        value,
                        calc(bits[removed],
                             previous[parentBase + parentPosition])
                    );
                }

                current[currentRank * size + removed] = value;
                answer = max(answer, value - l);
            }

            ++currentRank;

            uint32_t lowest = mask & (~mask + 1);
            uint32_t next = mask + lowest;
            if (next >= limit)
                break;

            mask = next | (((mask ^ next) / lowest) >> 2);
        }

        previous = std::move(current);
    }

    cout << fixed << setprecision(9) << min(answer, r - l) << '\n';
    return 0;
}

#include <iostream>
