using namespace std;

struct Light {
    double x, y, alpha;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    double l, r;
    cin >> n >> l >> r;

    vector<Light> p(n);
    const double pi = acos(-1.0);

    for (auto& light : p) {
        cin >> light.x >> light.y >> light.alpha;
        light.alpha *= pi / 180.0;
    }

    auto calc = [&](int idx, double s) {
        double beta = p[idx].alpha - atan2(p[idx].x - s, p[idx].y);
        return p[idx].x + tan(beta) * p[idx].y;
    };

    vector<double> dp(1 << n, l);
    double ans = 0.0;

    for (int mask = 1; mask < (1 << n); ++mask) {
        double best = l;

        for (int bits = mask; bits; bits &= bits - 1) {
            int i = __builtin_ctz(bits);
            best = max(best, calc(i, dp[mask ^ (1 << i)]));
        }

        dp[mask] = best;
        ans = max(ans, best - l);
    }

    cout << fixed << setprecision(9) << min(ans, r - l) << '\n';
    return 0;
}

#include <iostream>
#include <iomanip>
#include <cmath>
