using namespace std;

struct Light {
    double x, y, alpha;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    double l, r;
    cin >> n >> l >> r;

    vector<Light> p(n);
    const double PI = acos(-1.0);

    for (int i = 0; i < n; ++i) {
        cin >> p[i].x >> p[i].y >> p[i].alpha;
        p[i].alpha *= PI / 180.0;
    }

    if (n == 0) {
        cout << fixed << setprecision(9) << 0.0 << '\n';
        return 0;
    }

    const int totalMasks = 1 << n;
    const int statesPerLight = 1 << (n - 1);
    vector<double> dp(static_cast<size_t>(n) * statesPerLight);

    auto compressedMask = [](int mask, int bit) {
        const int lower = mask & ((1 << bit) - 1);
        const int upper = (mask >> (bit + 1)) << bit;
        return lower | upper;
    };

    auto state = [&](int light, int mask) -> double& {
        return dp[static_cast<size_t>(light) * statesPerLight +
                  compressedMask(mask, light)];
    };

    auto calc = [&](int idx, double s) {
        const double beta =
            p[idx].alpha - atan2(p[idx].x - s, p[idx].y);
        return p[idx].x + tan(beta) * p[idx].y;
    };

    double ans = 0.0;

    for (int mask = 1; mask < totalMasks; ++mask) {
        for (int i = 0; i < n; ++i) {
            if (!(mask & (1 << i)))
                continue;

            const int previousMask = mask ^ (1 << i);
            double value = l;

            if (previousMask == 0) {
                value = max(value, calc(i, l));
            } else {
                for (int j = 0; j < n; ++j) {
                    if (previousMask & (1 << j))
                        value = max(value, calc(i, state(j, previousMask)));
                }
            }

            state(i, mask) = value;
            ans = max(ans, value - l);
        }
    }

    cout << fixed << setprecision(9) << min(ans, r - l) << '\n';
    return 0;
}

